={{ (() => {
  const content = ($('Webhook').first().json.body.content || '').toLowerCase();

  const phrases = [
    'gostaria de mais informações',
    'gostaria de receber mais informações',
    'tenho interesse em',
    'quero ser contatado sobre este imóvel',
    'código do anúncio',
    'código da oferta',
    'encontrei no vivareal',
    'encontrei no zap',
    'que vi em wimoveis',
    'que vi no chaves na mão',
    'que encontrei no zap',
    'que encontrei no vivareal'
  ];

  const urls = [
    'vivareal.com.br',
    'zapimoveis.com.br',
    'imovelweb.com.br',
    'wimoveis.com.br',
    'chavesnamao.com.br',
    'fmiprime.com.br/imovel'
  ];

  const hasPhrase = phrases.some(p => content.includes(p));
  const hasUrl = urls.some(u => content.includes(u));

  return hasPhrase && hasUrl;
})() }}

