</descricao_visual_da_imagem>
<instrucao_ia>Acima está o que o cliente escreveu e a descrição técnica da imagem. Use ambos para responder com naturalidade.</instrucao_ia>`.trim();
  }

  // 4. Construção da resposta final (com tratativas de segurança pro sender)
  let nomeCliente = '';
  let telefoneCliente = '';
  try {
    nomeCliente = sender.name || '';
    telefoneCliente = sender.phone_number || '';
  } catch(e) {}

  const outputLines = [
    '### DADOS DO CLIENTE',
    `Nome: ${nomeCliente}`,
    `Telefone: ${telefoneCliente}`,
    '',
    '### CONTEXTO TEMPORAL (IMPORTANTE)',
    `Data e Hora Atual: ${dataHora}`,
    `Timezone: ${timezone}`,
    '',
    '### METADADOS DO CHAT',
    `ID_Conversa: ${conversationId}`,
    `ID_Mensagem: ${messageId}`,
    `Tipo_Mensagem: ${tipoMsgMeta}`
  ];

  // Adiciona a seção sobre o anúncio de forma dinâmica, apenas se existir
  if (referralBody && referralBody.trim() !== '') {
    outputLines.push(
      '',
      '### CONTEXTO DO ANÚNCIO (ORIGEM DO LEAD)',
      referralBody
    );
  }

  // Adiciona a última parte do payload
  outputLines.push(
    '',
    '### CONTEÚDO DA MENSAGEM PARA PROCESSAR',
    conteudoFinal || '(vazio)'
  );

  // Retorno formatado para a IA
  return outputLines.join('\n');
})()
}}

