function limparNome(nomeCompleto) {
  if (!nomeCompleto || !nomeCompleto.trim()) return '';
  let nome = nomeCompleto;
  nome = nome.normalize('NFKC');
  nome = nome.replace(/[^a-zA-ZÀ-ÿ '-]/g, '');
  nome = nome.replace(/ +/g, ' ').trim();
  if (!nome) return '';
  nome = nome.split(' ')[0];
  nome = nome.charAt(0).toUpperCase() + nome.slice(1).toLowerCase();
  return nome;
}

const row = $input.first().json.body || $input.first().json;

let telefone = String(row.TELEFONE || row.telefone || '');
telefone = telefone.replace(/\D/g, '');

if (telefone.startsWith('0')) {
  telefone = telefone.substring(1);
}

let semPais = telefone;
if (telefone.startsWith('55') && telefone.length >= 12) {
  semPais = telefone.substring(2);
}

if (semPais.length === 10) {
  semPais = semPais.substring(0, 2) + '9' + semPais.substring(2);
}

if (semPais.length > 11) {
  const ddd = semPais.substring(0, 2);
  const numero = semPais.slice(-9);
  semPais = ddd + numero;
}

const telefoneFormatado = semPais ? '55' + semPais : '';

const produtoInteressado = String(row['PRODUTO INTERESSADO'] || row.ref_imovel_cadastrado || '').trim();

const correcoes = {
  'torre di castoi': 'Torre Di Castroi',
};

let referencia = '';

const refMatch = produtoInteressado.match(/\d+/);

if (refMatch) {
  referencia = refMatch[0];
} else if (produtoInteressado) {
  const chave = produtoInteressado.toLowerCase();
  if (correcoes[chave]) {
    referencia = correcoes[chave];
  } else {
    referencia = produtoInteressado
      .toLowerCase()
      .split(' ')
      .map(p => p.charAt(0).toUpperCase() + p.slice(1))
      .join(' ');
  }
}

return [{ json: {
  name: limparNome(row.NOME || row.nome || ''),
  phone: telefoneFormatado,
  email: row.EMAIL || row.email || '',
  internalReference: referencia,
  origem: row.ORIGEM || row.origem || 'Trafego'
} }];

