  const url = String(a.data_url || a.url || '');
  let filename = (url.split('/').pop() || '').split('?')[0];
  try { filename = decodeURIComponent(filename); } catch {}
  const ext =
    String(a.extension || '').toLowerCase() ||
    (filename.includes('.') ? filename.split('.').pop().toLowerCase() : '');

  const imageExt = ['jpg','jpeg','png','gif','webp','bmp','tif','tiff','heic','heif','svg'];
  const audioExt = ['ogg','oga','opus','mp3','wav','m4a','aac','flac','amr','wma'];

  if (ft === 'audio' || audioExt.includes(ext)) return 'audio';
  if (ft === 'image' || imageExt.includes(ext)) return 'image';
  if (ext === 'pdf') return 'pdf';

  // doc/docx and everything else
  return 'other';
})()}}

